          const totalWins = toInt2(pickValue2(item, "totalWins", "TotalWins"), 0);
          const goingFirstGames = toInt2(pickValue2(item, "goingFirstGames", "GoingFirstGames"), 0);
          const goingFirstWins = toInt2(pickValue2(item, "goingFirstWins", "GoingFirstWins"), 0);
          const goingSecondGames = toInt2(pickValue2(item, "goingSecondGames", "GoingSecondGames"), 0);
          const goingSecondWins = toInt2(pickValue2(item, "goingSecondWins", "GoingSecondWins"), 0);
          const updatedAt = pickValue2(item, "updatedAtUtc", "UpdatedAtUtc");
